// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
/**
 * The simple pull quote (model pull-quote@1): the words in a blockquote, then the author (names the section), a
 * role line and the source as a link, in a figure. Axes: layout (rule: a bar in the primary token at the start,
 * centered: centred, no bar).
 */
import { type ReactNode } from "react";
import { Block, Box, Container, LinkPlain, Stack, Text } from "../compose";
import { cn, urlOf } from "../utils";

export type PullQuoteSimpleProps = {
  id: string;
  quote: string;
  title: string;
  description?: string;
  sourceLabel?: string;
  sourceHref?: string;
  padding?: "compact" | "standard" | "spacious";
  layout?: "rule" | "centered";
  landmarkLabel?: string;
};

export function PullQuoteSimple({
  id,
  quote,
  title,
  description = "",
  sourceLabel = "",
  sourceHref = "",
  padding = "standard",
  layout = "rule",
  landmarkLabel,
}: PullQuoteSimpleProps) {
  const titleId = id + "-title";
  const frame =
    (layout as string) === "rule" ? "flex flex-row gap-6"
    : "flex flex-col items-center";
  const copyAlign = ((layout as string) === "rule") ? "start" : "center";
  const copyText = ((layout as string) === "rule") ? "text-start" : "text-center";
  return (
    <Block
      tag="section"
      className={
        (padding as string) === "compact" ? "py-8 lg:py-16"
        : (padding as string) === "spacious" ? "py-24 lg:py-40"
        : "py-16 lg:py-32"
      }
      aria-labelledby={(landmarkLabel ? undefined : titleId)}
      aria-label={landmarkLabel}
      data-slot="pull-quote-simple"
    >
      <Container className="mx-auto w-full max-w-6xl px-4">
        <Box tag="figure" className={cn("mx-auto max-w-3xl", frame)}>
          {((layout as string) === "rule") ? (
            <Box className="w-2 shrink-0 self-stretch rounded-full bg-primary" aria-hidden="true" />
          ) : null}
          <Stack gap="6" align={copyAlign}>
            <Text tag="blockquote" size="2xl" weight="medium" className={cn("tracking-tight", copyText)}>
              {quote}
            </Text>
            <Stack gap="2" align={copyAlign}>
              <Text size="base" weight="semibold" className={copyText} id={titleId}>
                {title}
              </Text>
              {description ? (
                <Text size="sm" className={cn("text-muted-foreground", copyText)}>
                  {description}
                </Text>
              ) : null}
              {(sourceLabel && sourceHref) ? (
                <LinkPlain href={urlOf(sourceHref)} className="text-primary hover:text-foreground">
                  <Text size="sm">
                    {sourceLabel}
                  </Text>
                </LinkPlain>
              ) : null}
            </Stack>
          </Stack>
        </Box>
      </Container>
    </Block>
  );
}
